import{_ as e,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Enhancing Ceph Monitoring at CERN- Our Approach and Solutions - R. Valverde Cameselle & E. Bocchi","description":"","frontmatter":{"title":"Enhancing Ceph Monitoring at CERN- Our Approach and Solutions - R. Valverde Cameselle & E. Bocchi","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Monitoring","High Availability","Scalability","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Enhancing_Ceph_Monitoring_at_CERN_-_Our_Approach_and_Solutions_-_R._Valverde_Cameselle_E._Bocchi.md","filePath":"posts/2025/Enhancing_Ceph_Monitoring_at_CERN_-_Our_Approach_and_Solutions_-_R._Valverde_Cameselle_E._Bocchi.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Enhancing_Ceph_Monitoring_at_CERN_-_Our_Approach_and_Solutions_-_R._Valverde_Cameselle_E._Bocchi.md"};function r(n,a,h,_,c,s){return l(),i("div",null,[...a[0]||(a[0]=[o('<h3 id="cern-ceph监控方案会议纪要" tabindex="-1">CERN Ceph监控方案会议纪要 <a class="header-anchor" href="#cern-ceph监控方案会议纪要" aria-label="Permalink to &quot;CERN Ceph监控方案会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>时间</strong>：未明确（上午会议）</li><li><strong>主讲人</strong>： <ul><li>Enrico（CERN SEF技术负责人）</li><li>Roberto（CERN SEF运维及监控负责人）</li></ul></li><li><strong>主题</strong>：CERN如何通过增强监控方案优化Ceph存储系统的运维。</li></ul><h4 id="cern及ceph背景介绍" tabindex="-1">CERN及Ceph背景介绍 <a class="header-anchor" href="#cern及ceph背景介绍" aria-label="Permalink to &quot;CERN及Ceph背景介绍&quot;">​</a></h4><ul><li>CERN是全球最大的粒子物理实验室，位于法国-瑞士边境，运营着大型强子对撞机（LHC），产生海量数据。</li><li>Ceph部署在CERN的存储环境中，规模约100 PB，包括object存储（RADOSGW）、block存储（RBD）和file存储（CephFS），用于IT服务、实验数据存储、备份和虚拟化存储。</li></ul><h4 id="监控架构演进" tabindex="-1">监控架构演进 <a class="header-anchor" href="#监控架构演进" aria-label="Permalink to &quot;监控架构演进&quot;">​</a></h4><ul><li>CERN早期使用Graphite进行监控，但面临数据查询和降采样问题。</li><li>2018年转型至Prometheus + Thanos，实现统一查询接口和自动降采样。</li><li>监控架构包括Prometheus、Thanos、Node Exporter、自定义脚本等，支持多数据中心双活部署。</li></ul><h4 id="关键监控场景与故障排查" tabindex="-1">关键监控场景与故障排查 <a class="header-anchor" href="#关键监控场景与故障排查" aria-label="Permalink to &quot;关键监控场景与故障排查&quot;">​</a></h4><ul><li>监控CephFS问题，如客户端会话和MDS内存泄漏。</li><li>监控多站点S3同步，通过自定义脚本解析同步状态。</li><li>联动基础设施监控，如网络问题、OpenStack OVN和Kubernetes。</li></ul><h4 id="告警与自动化" tabindex="-1">告警与自动化 <a class="header-anchor" href="#告警与自动化" aria-label="Permalink to &quot;告警与自动化&quot;">​</a></h4><ul><li>分级告警，低优先级通过邮件/ServiceNow工单，高优先级通过Mattermost/Telegram即时通知。</li><li>硬件退役时，利用标签快速定位受影响节点。</li></ul><h4 id="后续计划与社区协作" tabindex="-1">后续计划与社区协作 <a class="header-anchor" href="#后续计划与社区协作" aria-label="Permalink to &quot;后续计划与社区协作&quot;">​</a></h4><ul><li>改进MDS慢请求监控，推动上游修复误导性日志。</li><li>加入Ceph科学用户组，分享HPC/研究场景经验。</li></ul><h4 id="q-a重点" tabindex="-1">Q&amp;A重点 <a class="header-anchor" href="#q-a重点" aria-label="Permalink to &quot;Q&amp;A重点&quot;">​</a></h4><ul><li>监控高可用：Thanos支持多实例读写，但CERN选择简单双活。</li><li>部署工具：主要用原生包，少数集群试用Cephadm。</li><li>硬件故障响应：依赖基础架构监控，按影响范围分级处理。</li></ul><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li>短期：优化MDS慢请求监控标签。</li><li>长期：评估Thanos多活自动化。</li></ul>',17)])])}const p=e(t,[["render",r]]);export{u as __pageData,p as default};
